const raw = $input.first().json;
const body = raw.body || raw;
const leadId = body.lead_id || body.id;

const isValid = Boolean(leadId && typeof leadId === 'string' && leadId.trim().length > 0);

return [{
  json: {
    lead_id: leadId ? leadId.trim() : null,
    override_budget: Number(body.budget) || null,
    override_notes: body.interaction_notes || body.notes || null,
    scored_by: body.scored_by || 'AI_Sales_Agent_Scorer',
    is_valid_payload: isValid,
    received_at: new Date().toISOString()
  }
}];

