const lead = $input.first().json;
const webhookInput = $('Code (Validate Inbound Payload)').first().json;

let metadata = lead.metadata || {};
if (typeof metadata === 'string') {
  try {
    metadata = JSON.parse(metadata);
  } catch (e) {
    metadata = {};
  }
}

// BANT Framework extraction: Budget, Authority, Need, Timeline
const budget = webhookInput.override_budget || Number(metadata.budget) || 0;
const notes = webhookInput.override_notes || metadata.notes || metadata.interaction_notes || '';
const email = (lead.email || '').trim().toLowerCase();
const company = (lead.company_name || 'Doanh Nghiệp').trim();
const isCorporateEmail = Boolean(email && !/@(gmail|yahoo|hotmail|outlook)\.com$/i.test(email));

return [{
  json: {
    ...lead,
    metadata_parsed: metadata,
    extracted_features: {
      budget: budget,
      notes: notes,
      company: company,
      email: email,
      is_corporate_email: isCorporateEmail
    }
  }
}];

const item = $input.first().json;
const f = item.extracted_features;

// Xây dựng structured prompt phục vụ mô hình LLM chấm điểm
const prompt = `Bạn là chuyên gia phân tích chất lượng khách hàng tiềm năng B2B (AI Sales Analyst).
Hãy đánh giá lead dựa trên các thông số BANT sau:
- Khách hàng: ${item.first_name || ''} ${item.last_name || ''}
- Doanh nghiệp: ${f.company}
- Email: ${f.email} (Email doanh nghiệp: ${f.is_corporate_email ? 'Có' : 'Không'})
- Ngân sách dự kiến: $${f.budget}
- Ghi chú nhu cầu & tương tác: "${f.notes}"

Hãy phân tích và cho điểm tiềm năng theo thang 0 - 100, xếp hạng HOT/WARM/COLD và đưa ra hành động đề xuất.`;

return [{
  json: {
    ...item,
    ai_prompt: prompt,
    prepared_at: new Date().toISOString()
  }
}];

const item = $input.first().json;
const f = item.extracted_features;

// Thuật toán chấm điểm chuẩn B2B BANT
let baseScore = 35;
let reasons = [];
let tags = [];

// 1. Tiêu chí Budget (Ngân sách)
if (f.budget >= 10000) {
  baseScore += 30;
  reasons.push("Ngân sách dự kiến lớn (>= $10,000)");
  tags.push("High-Budget");
} else if (f.budget >= 3000) {
  baseScore += 15;
  reasons.push("Ngân sách trung bình ($3,000 - $10,000)");
  tags.push("Mid-Budget");
} else {
  reasons.push("Chưa xác định ngân sách cụ thể");
}

// 2. Tiêu chí Need & Timeline (Mức độ cấp thiết)
if (/gấp|enterprise|báo giá|triển khai ngay|hợp đồng|chốt sale/i.test(f.notes)) {
  baseScore += 25;
  reasons.push("Nhu cầu cấp thiết, quan tâm sâu giải pháp Enterprise");
  tags.push("High-Intent", "Ready-To-Buy");
} else if (/tìm hiểu|tư vấn|tham khảo/i.test(f.notes)) {
  baseScore += 10;
  reasons.push("Đang ở giai đoạn tìm hiểu thị trường");
  tags.push("Exploring");
}

// 3. Tiêu chí Authority (Định danh doanh nghiệp)
if (f.is_corporate_email) {
  baseScore += 10;
  reasons.push("Sử dụng email tên miền doanh nghiệp chính chủ");
  tags.push("Verified-Domain");
} else {
  reasons.push("Sử dụng email cá nhân (Gmail/Yahoo)");
}

const finalScore = Math.min(100, Math.max(0, baseScore));

// Xếp phân khúc Tier & Action
let tier = 'COLD';
let recommendedAction = 'Nuôi dưỡng tự động qua chuỗi Email Marketing';

if (finalScore >= 80) {
  tier = 'HOT';
  recommendedAction = 'Bàn giao ngay cho Senior Sales Agent gọi điện chốt hợp đồng trong 2h';
} else if (finalScore >= 55) {
  tier = 'WARM';
  recommendedAction = 'Gửi bản demo giải pháp và xếp lịch hẹn tư vấn kỹ thuật trong 24h';
}

return [{
  json: {
    lead_id: item.id,
    lead_name: `${item.first_name || ''} ${item.last_name || ''}`.trim() || 'Khách Hàng',
    company_name: f.company,
    email: f.email,
    final_score: finalScore,
    tier: tier,
    tags: tags,
    recommended_action: recommendedAction,
    reasoning: reasons.join("; "),
    scored_at: new Date().toISOString()
  }
}];

const scoredData = $('Code (AI Scoring & Segment Engine)').first().json;

const isHighPriority = scoredData.tier === 'HOT' || scoredData.tier === 'WARM';
const alertMessage = `🔥 *CẢNH BÁO LEAD TIỀM NĂNG CAO (WF-13)*\n` +
  `• *Khách hàng:* ${scoredData.lead_name} (${scoredData.company_name})\n` +
  `• *Email:* ${scoredData.email}\n` +
  `• *AI Score:* *${scoredData.final_score}/100* (Phân khúc: *${scoredData.tier}*)\n` +
  `• *Tags:* \`${scoredData.tags.join(', ')}\`\n` +
  `• *Hành động đề xuất:* ${scoredData.recommended_action}\n` +
  `• *Lý do AI:* ${scoredData.reasoning}`;

return [{
  json: {
    ...scoredData,
    is_high_priority: isHighPriority,
    sales_alert_message: alertMessage
  }
}];
